/* V30: deterministic offline financial assistant. No external API, no invented data. */
function aiStats(m=cur){
 const tx=S.tx.filter(x=>x&&x.d&&mk(x.d)===m);
 const total=k=>tx.filter(x=>x.k===k).reduce((n,x)=>n+(Number(x.a)||0),0);
 const inc=total('inc'),exp=total('exp'),prev=sum('exp',m===cur?prevKey():m);
 const categories={};tx.filter(x=>x.k==='exp').forEach(x=>{const k=x.cat||'سایر';categories[k]=(categories[k]||0)+(Number(x.a)||0)});
 return {inc,exp,net:inc-exp,prev,count:tx.filter(x=>['inc','exp'].includes(x.k)).length,
 categories,budget:Number(S.bud)||0,month:m};
}
function aiInsight(){
 const a=aiStats(),top=Object.entries(a.categories).sort((x,y)=>y[1]-x[1])[0];
 if(!a.count)return {mood:'welcome',message:'هنوز درآمد یا هزینه‌ای در این ماه ثبت نشده؛ با اولین تراکنش شروع کنیم.'};
 if(a.exp>a.inc)return {mood:'thoughtful',message:'هزینه‌های ثبت‌شده این ماه از درآمد بیشتر است. بهتر است جزئیات مخارج را بررسی کنیم.'};
 if(a.budget&&a.exp>=a.budget)return {mood:'alert',message:'هزینه‌های ثبت‌شده به سقف بودجه ماهانه رسیده است.'};
 if(a.prev>0&&a.exp>a.prev*1.3)return {mood:'alert',message:'هزینه ثبت‌شده این ماه بیش از ۳۰٪ از ماه قبل بیشتر است؛ مقایسه را با توجه به روزهای سپری‌شده انجام بده.'};
 if(a.net>0)return {mood:'happy',message:'تا اینجای ماه درآمد ثبت‌شده بیشتر از هزینه بوده است.'};
 return {mood:'calm',message:'درآمد و هزینه ثبت‌شده این ماه برابر است.'};
}
function aiAnswer(q){
 const a=aiStats(),t=q.trim().replace(/[ي]/g,'ی').replace(/[ك]/g,'ک');
 if(!t)return 'یک سؤال درباره درآمد، هزینه، بودجه، پس‌انداز یا وضعیت ماه جاری بنویس.';
 if(!a.count)return 'هنوز تراکنش درآمد یا هزینه‌ای برای ماه انتخابی ثبت نشده است. پس از ثبت اطلاعات، می‌توانم آن‌ها را تحلیل کنم.';
 if(/بودجه|سقف/.test(t))return a.budget?`بودجه ماهانه ${fa(a.budget)} تومان است؛ ${fa(a.exp)} تومان هزینه ثبت شده و ${fa(Math.max(0,a.budget-a.exp))} تومان از بودجه باقی مانده است.${a.exp>a.budget?' هزینه از سقف بودجه عبور کرده است.':''}`:'هنوز بودجه ماهانه تعیین نشده است. از تنظیمات می‌توانی بودجه را مشخص کنی.';
 if(/دسته|بیشتر|بالاترین|خرج/.test(t)){const top=Object.entries(a.categories).sort((x,y)=>y[1]-x[1])[0];return top?`بیشترین هزینه دسته‌بندی‌شده این ماه مربوط به «${top[0]}» با ${fa(top[1])} تومان است. کل هزینه ثبت‌شده ${fa(a.exp)} تومان است.`:'هزینه دسته‌بندی‌شده‌ای در این ماه ثبت نشده است.'}
 if(/ماه قبل|مقایسه|روند/.test(t)){const pi=sum('inc',prevKey()),pe=sum('exp',prevKey());return `ماه انتخابی: درآمد ${fa(a.inc)} و هزینه ${fa(a.exp)} تومان. ماه قبل از ماه جاری: درآمد ${fa(pi)} و هزینه ${fa(pe)} تومان. توجه: ماه جاری ممکن است هنوز کامل نشده باشد.`}
 if(/پس‌انداز|مازاد|سود|مانده/.test(t))return `تفاضل درآمد و هزینه ثبت‌شده در ماه انتخابی ${fa(a.net)} تومان است. این عدد موجودی بانکی یا سود قطعی کسب‌وکار نیست و اقساط، طلب‌ها و انتقال داخلی در آن دوباره‌شماری نشده‌اند.`;
 if(/درآمد/.test(t))return `مجموع درآمد ثبت‌شده در ماه انتخابی ${fa(a.inc)} تومان است.`;
 if(/هزینه/.test(t))return `مجموع هزینه ثبت‌شده در ماه انتخابی ${fa(a.exp)} تومان است.`;
 return `خلاصه ماه انتخابی: درآمد ${fa(a.inc)}، هزینه ${fa(a.exp)} و مازاد ${fa(a.net)} تومان. می‌توانی درباره «بودجه»، «بیشترین خرج»، «مقایسه ماه قبل» یا «پس‌انداز» بپرسی.`;
}
