let LK='all';function listSheet(k){LK=k;if(k==='col')return colSheet();if(k==='debt')return debtSheet();if(k==='day')return daySheet();if(k==='bank')return bankSheet();const l=S.tx.filter(x=>k==='all'||x.k===k).sort((a,b)=>k==='ins'?(a.d<b.d?-1:1):(a.d<b.d?1:-1));
open(`<h2>${k==='all'?'همه تراکنش‌ها':k==='col'?'حساب همکار':K[k].n+'‌ها'}</h2>${k==='all'?'<input class="f" placeholder="جستجو در تراکنش‌ها" oninput="const q=this.value;document.querySelectorAll(\'#ls .item\').forEach(e=>e.style.display=e.textContent.includes(q)?\'\':\'none\')">':''}<div id="ls">${l.length?l.map(x=>item(x)).join(''):'<div class="empty">هنوز چیزی ثبت نشده.</div>'}</div>
${k==='all'?'':`<button class="btn" data-a="add" data-k="${k}">+ ثبت ${K[k].n}</button>`}`)}
