if(r<0)L.push('هزینه‌ها از درآمد بیشتر شده؛ هزینه‌های غیرضروری را مرور کنید.');else if(inc&&r<20)L.push('پس‌انداز ماه کمتر از ۲۰٪ درآمد است.');
