const dueSoon=S.tx.filter(x=>x.k==='ins'&&x.d>=D()&&x.d<=D(7));if(dueSoon.length)L.push(`${dueSoon.length.toLocaleString('fa-IR')} قسط تا هفت روز آینده سررسید دارد.`);
