;

S.vc=S.vc||[];S.vp=S.vp||[];S.vs=S.vs||[];S.vx=S.vx||[];
const pad=n=>String(n).padStart(2,'0'),iso=g=>g[0]+'-'+pad(g[1])+'-'+pad(g[2]);
function jv(){const[y,m,d]=['#jy','#jm','#jd'].map(q=>+$(q).value),s=iso(j2g(y,m,d));return jp(s).join()===[y,m,d].join()?s:null}
function endOf(s,mo){let[y,m,d]=jp(s);m+=mo;y+=Math.floor((m-1)/12);m=(m-1)%12+1;d=Math.min(d,m<=6?31:m<12?30:29);return iso(j2g(y,m,d))}
const rem=x=>x.sale-x.paid,sm=a=>[a.reduce((s,x)=>s+x.sale,0),a.reduce((s,x)=>s+x.sale-x.cost,0)];
