function stat(){const t=D(),w=D(-6),m=mk(t),f=p=>S.vs.filter(x=>p(x.d));return{d:sm(f(x=>x===t)),w:sm(f(x=>x>=w)),m:sm(f(x=>mk(x)===m)),act:S.vs.filter(x=>x.e>=t).length,debt:S.vs.reduce((s,x)=>s+rem(x),0),ex:S.vx.filter(x=>mk(x.d)===m).reduce((s,x)=>s+x.a,0)}}
